pub fn adaptive_sort<T: Ord>(a: &mut [T]) {
    let n = a.len();
    if n > 1 {
        introsort(a, 0, n - 1, 2 * (n as f64).log2() as usize);
    }
}

fn introsort<T: Ord>(a: &mut [T], lo: usize, hi: usize, d: usize) {
    if hi <= lo { return; }
    if hi - lo < 20 {
        insertion(a, lo, hi);
    } else if d == 0 {
        a[lo..=hi].sort_unstable();
    } else {
        let (lt, gt) = part3(a, lo, hi);
        if lt > lo { introsort(a, lo, lt - 1, d - 1); }
        if gt < hi { introsort(a, gt + 1, hi, d - 1); }
    }
}

fn insertion<T: Ord>(a: &mut [T], lo: usize, hi: usize) {
    for i in (lo + 1)..=hi {
        let mut j = i;
        while j > lo && a[j - 1] > a[j] { a.swap(j, j - 1); j -= 1; }
    }
}

// 3-way partition (Dutch National Flag), median-of-three pivot moved to lo.
fn part3<T: Ord>(a: &mut [T], lo: usize, hi: usize) -> (usize, usize) {
    let m = lo + (hi - lo) / 2;
    if a[m] < a[lo] { a.swap(lo, m); }
    if a[hi] < a[lo] { a.swap(lo, hi); }
    if a[hi] < a[m] { a.swap(m, hi); }
    a.swap(lo, m);

    let mut lt = lo;
    let mut i = lo + 1;
    let mut gt = hi;
    while i <= gt {
        if a[i] < a[lt] {
            a.swap(lt, i);
            lt += 1;
            i += 1;
        } else if a[i] > a[lt] {
            a.swap(i, gt);
            if gt == 0 { break; }
            gt -= 1;
        } else {
            i += 1;
        }
    }
    (lt, gt)
}
